fused_bn_gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bn_gelu_kernel(
    const float* input,
    const float* running_mean,
    const float* running_var,
    const float* weight,
    const float* bias,
    float epsilon,
    float* output,
    int num_features,
    int total_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int feature_idx = idx % num_features;
    float x = input[idx];
    float mean = running_mean[feature_idx];
    float var = running_var[feature_idx];
    float inv_std = rsqrtf(var + epsilon);
    float scaled = (x - mean) * inv_std * weight[feature_idx] + bias[feature_idx];
    output[idx] = scaled * 0.5f * (1.0f + erff(scaled * 0.7071067811865475f));
}

torch::Tensor fused_bn_gelu_cuda(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float epsilon
) {
    auto output = torch::empty_like(input);
    int total_elements = input.numel();
    int num_features = input.size(1);

    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    fused_bn_gelu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        epsilon,
        output.data_ptr<float>(),
        num_features,
        total_elements
    );

    return output;
}
"""

# GroupNorm kernel
group_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void group_norm_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    int batch_size,
    int num_features,
    int num_groups,
    float epsilon,
    float* output
) {
    extern __shared__ float smem[];

    int group_id = blockIdx.y;
    int sample_id = blockIdx.x;
    int features_per_group = num_features / num_groups;
    int group_offset = group_id * features_per_group;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for(int i=threadIdx.x; i<features_per_group; i+=blockDim.x) {
        float val = input[sample_id * num_features + group_offset + i];
        sum += val;
        sum_sq += val * val;
    }

    smem[threadIdx.x] = sum;
    smem[threadIdx.x + blockDim.x] = sum_sq;
    __syncthreads();

    for(int stride=blockDim.x/2; stride>0; stride>>=1) {
        if(threadIdx.x < stride) {
            smem[threadIdx.x] += smem[threadIdx.x + stride];
            smem[threadIdx.x + blockDim.x] += smem[threadIdx.x + blockDim.x + stride];
        }
        __syncthreads();
    }

    float mean = smem[0] / features_per_group;
    float var = (smem[blockDim.x] / features_per_group) - (mean * mean);
    float inv_std = rsqrtf(var + epsilon);

    for(int i=threadIdx.x; i<features_per_group; i+=blockDim.x) {
        int idx = sample_id * num_features + group_offset + i;
        float normalized = (input[idx] - mean) * inv_std;
        output[idx] = normalized * weight[group_offset + i] + bias[group_offset + i];
    }
}

torch::Tensor group_norm_cuda(
    torch::Tensor input,
    int num_groups,
    torch::Tensor weight,
    torch::Tensor bias,
    float epsilon
) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_features = input.size(1);

    dim3 grid(batch_size, num_groups);
    int block_size = 256;
    size_t smem_size = 2 * block_size * sizeof(float);

    group_norm_kernel<<<grid, block_size, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        batch_size,
        num_features,
        num_groups,
        epsilon,
        output.data_ptr<float>()
    );

    return output;
}
"""

# Fused Mean + ReLU kernel
mean_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mean_relu_kernel(const float* input, float* output, int num_features, int total_samples) {
    int sample_id = blockIdx.x * blockDim.x + threadIdx.x;
    if(sample_id >= total_samples) return;

    float sum = 0.0f;
    for(int i=0; i<num_features; ++i) {
        sum += input[sample_id * num_features + i];
    }
    output[sample_id] = fmaxf(sum / num_features, 0.0f);
}

torch::Tensor fused_mean_relu_cuda(torch::Tensor input, int num_features) {
    int batch_size = input.size(0);
    auto output = torch::empty(batch_size, 1, input.options());

    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    mean_relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_features,
        batch_size
    );

    return output;
}
"""

