class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups):
        super().__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.bn = nn.BatchNorm1d(out_features)
        self.gn_weight = nn.Parameter(torch.ones(out_features))
        self.gn_bias = nn.Parameter(torch.zeros(out_features))
        self.num_groups = num_groups
        self.eps = 1e-5

    def forward(self, x):
        x = self.gemm(x)
        x = fused_bn_gelu.fused_bn_gelu_cuda(
            x, 
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.weight,
            self.bn.bias,
            self.bn.eps
        )
        x = group_norm.group_norm_cuda(
            x,
            self.num_groups,
            self.gn_weight,
            self.gn_bias,
            self.eps
        )
        x = fused_mean_relu.fused_mean_relu_cuda(x, x.size(1))
        return x
